# Let me try to find a pattern by working backwards from outputs
inputs = ['bd', 'hj', 'dkzcc', 'xz', 'wj']
outputs = ['bd', 'hdgu', 'dicfxhcc', 'xfxh', 'wdgu']

# Let me try to identify common character mappings
print("Looking for character replacements:")

# Check if there are consistent single character replacements
replacements = {}

# Check if we can find simple character-to-character mappings
for inp, outp in zip(inputs, outputs):
    # Pad to same length for easier comparison
    max_len = max(len(inp), len(outp))
    padded_inp = inp.ljust(max_len)
    padded_outp = outp.ljust(max_len)

    for i in range(max_len):
        if i < len(inp) and i < len(outp) and inp[i] != outp[i]:
            if inp[i] not in replacements:
                replacements[inp[i]] = outp[i]
            else:
                # If already mapped, check consistency
                if replacements[inp[i]] != outp[i]:
                    print(f"Conflict: '{inp[i]}' maps to both '{replacements[inp[i]]}' and '{outp[i]}'")

print("Potential single character replacements:", replacements)

# Now let me also check for multi-character patterns
print("\nChecking for multi-character patterns...")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' -> '{outp}'")

    # Look for substrings that might be replaced
    if len(inp) <= 3 and len(outp) <= 3:
        # This is likely to be a direct replacement
        print(f"  Direct replacement: '{inp}' -> '{outp}'")

